## Si l'écart de production est très persistant


::: {#cell-fig-ogmce .cell}

```{.r .cell-code .hidden}
ogmce <- sourcoise::sourcoise("ajust/simulations ajustement mceog.r")

ajustl <- c("0.1"="ajustement lent", "0.3" = "ajustement moyen", "0.5"="ajustement rapide")

gminog <- ogmce$trajectoires |> 
  filter(year>=2025, year<=2050, mult=="fixe", ibs %in% c("optimal"),
         dstar %in% c("d*=110%"), og_mce %in% c(0.1, 0.3, 0.5),
         ecstar %in% c(0), variable %in% c("ibc", "og")) |> 
  mutate(
    ajustl = ajustl[str_c(og_mce)],
    tooltip = glue(
  "<b>{year}</b>
  multiplicateur à 1 an: {og_dep} ; {ajustl} ({og_mce})
  Cumul d'impulsion: {round(mean*100,2)}%")) |> 
  ggplot() +
  aes(y = mean, ymin=q0.25, ymax =q0.75, x = year, color =  og_dep, group=og_dep) +
  # geom_ribbon(aes(ymin=q0.25, ymax=q0.75, fill = og_mce),
  #             alpha = 0.2) +
  geom_line(
    alpha = 1, size = 0.1, linewidth = 0.2) +
  geom_point_interactive(
    aes(tooltip=tooltip, data_id = year),
    data = ~filter(.x, year%in%c(2029, 2045, 2050)), size = 0.5) +
 scale_y_continuous(
    labels=scales::label_percent(1),
    oob = scales::squish)+
  scale_x_continuous(breaks = c(2030, 2040, 2050), 
                     labels = date1,
                     minor_breaks = scales::breaks_width(1)) +
  guides(color = guide_colorbar(title = "multitplicateur  \nà 1 an"),
         fill = "none",
         x = guide_axis(minor.ticks = TRUE)) +
  scale_color_distiller(palette="Greens", direction = 1)+
  facet_grid(
    cols=vars(variable), rows=vars(og_mce),
    labeller = labeller(
      variable = c(ibc = "Cumul des impulsions", og = "Ecart de production"),
      og_mce = ajustl) )+
  theme_ofce(
    legend.position.inside = c(0.95, 0.05),
    legend.direction = "horizontal",
    legend.justification = c(1,0),
    legend.key.width = unit(12, "pt"),
    legend.text = element_text(hjust=.5),
    legend.text.position = "bottom",
    axis.text.x = element_text(hjust=0, size = rel(0.9)),
    legend.title = marquee::element_marquee(vjust = .5),
    panel.spacing = unit(5, "pt") )+
  xlab(NULL)+
  ylab("Cumul des impulsions")

girafy(gminog, 1.5)
```

